// Obtener datos de nodos anteriores
const datosMsg  = $('Extraer Datos Mensaje').item.json;
const historial = $('Consulta Historial').all();
const baseCon   = $('Consulta Base Conocimiento').all();

// Construir historial de conversación
let historialTexto = '';
if (historial && historial.length > 0) {
  // Los resultados vienen en orden DESC, invertir para mostrar cronológico
  const rows = historial.map(i => i.json).reverse();
  historialTexto = rows.map(r => {
    const quien = r.rol === 'user' ? '👤 Instructor' : '🤖 Sera';
    return `${quien}: ${r.mensaje}`;
  }).join('\n');
}

// Construir base de conocimiento
let contextoSena = '';
if (baseCon && baseCon.length > 0) {
  contextoSena = baseCon.map(i => {
    const r = i.json;
    return `[${r.categoria} - ${r.documento}]\n${r.informacion_detallada}`;
  }).join('\n\n');
}

const textoFinal = datosMsg.texto || datosMsg.caption || '[mensaje vacío]';

return [{
  json: {
    telefono:      datosMsg.telefono,
    pushName:      datosMsg.pushName || 'Instructor',
    chatInput:     textoFinal,
    historialChat: historialTexto,
    contextoSena:  contextoSena,
    origen:        'ia'
  }
}];

const LIMITE = 5, VENTANA = 60000;
const tel = $input.item.json.body?.data?.key?.remoteJid?.replace('@s.whatsapp.net','') || 'unknown';
const ahora = Date.now();

const redis = require('redis');
const client = redis.createClient({ socket: { host: 'redis', port: 6379 } });
await client.connect();

try {
  const key = `sera:rl:${tel}`;
  const raw = await client.lRange(key, 0, -1);
  const tiempos = raw.map(Number).filter(t => ahora - t < VENTANA);
  const lim = tiempos.length >= LIMITE;

  if (!lim) tiempos.push(ahora);

  await client.del(key);
  if (tiempos.length) {
    await client.rPush(key, tiempos.map(String));
    await client.expire(key, Math.ceil(VENTANA / 1000));
  }

  return [{
    json: {
      ...$input.item.json,
      telefono: tel,
      rateLimitado: lim,
      msgRL: lim ? `⏳ Demasiados mensajes. Espera ${Math.ceil((VENTANA - (ahora - tiempos[0])) / 1000)}s.` : ''
    }
  }];
} finally {
  await client.disconnect();
}

const prev = $input.item.json;
const body = prev.body || {};
const data = body.data || {};
const msgType = prev.msgType || data.messageType || '';

// Prioriza el texto que ya traiga la rama (texto directo o audio transcrito)
const texto = prev.texto
           || data.message?.conversation
           || data.message?.extendedTextMessage?.text
           || '';

const imgMsg   = data.message?.imageMessage   || null;
const audioMsg = data.message?.audioMessage   || null;
const docMsg   = data.message?.documentMessage || null;

const caption = prev.caption || imgMsg?.caption || audioMsg?.caption || '';

return [{
  json: {
    ...prev,
    texto,
    caption,
    pushName: prev.pushName || data.pushName || '',
    msgType,
    esPtt: audioMsg?.ptt === true,
    tieneImagen: !!imgMsg,
    tieneAudio:  !!audioMsg,
    tieneDoc:    !!docMsg,
    imgMsg:   imgMsg   ? JSON.stringify(imgMsg)   : null,
    audioMsg: audioMsg ? JSON.stringify(audioMsg) : null,
    docMsg:   docMsg   ? JSON.stringify(docMsg)   : null,
    msgKey:   data.key ? JSON.stringify(data.key) : (prev.msgKey || null)
  }
}];

// Obtener datos del nodo anterior (LLM)
const respuestaLLM = $input.first().json.text
                  || $input.item.json.content 
                  || $input.item.json.message 
                  || $input.item.json.choices?.[0]?.message?.content
                  || $input.item.json.output
                  || '⚠️ No se pudo generar una respuesta';

// Obtener teléfono del nodo Extraer Datos Mensaje
const telefono = $('Extraer Datos Mensaje').first().json.telefono;
const textoOriginal = $('Extraer Datos Mensaje').first().json.texto;

return [{
  json: {
    telefono: telefono,
    text: respuestaLLM,
    response: respuestaLLM,
    mensaje: respuestaLLM,
    pregunta_log: textoOriginal || 'Consulta IA'
  }
}];

// Asegurar que todos los campos existan
const telefono = $input.item.json.telefono || '0000000000';
const mensaje = $input.item.json.mensaje || 'Sin respuesta';
const pregunta_log = $input.item.json.pregunta_log || 'Consulta';
const origen = $input.item.json.origen || 'ia';

return [{
  json: {
    telefono,
    mensaje,
    pregunta_log,
    origen,
    // Validar que no sean undefined o null
    telefonoValido: telefono && telefono !== 'undefined' && telefono !== 'null',
    mensajeValido: mensaje && mensaje !== 'undefined' && mensaje !== 'null'
  }
}];

// Obtener mensaje e información de entrada
const item = $input.item.json;
const textoRaw = item.texto || item.mensaje || item.chatInput || '';
const texto = textoRaw.toLowerCase().trim();

// Patrones de detección para coordinador
const regexResumen = /\b(resumen|global|estadistica|estadisticas|total|cumplimiento|tasa|reporte|general|cuantos informes|cuántos informes|cuanto informe)\b/i;
const regexCargaron = /\b(quien cargo|quién cargó|quienes cargaron|quiénes cargaron|quien subio|quién subió|instructores que cargaron|cargaron|subieron|ya cargaron)\b/i;
const regexPendientes = /\b(quien falta|quién falta|quienes faltan|quiénes faltan|no han cargado|sin cargar|no han subido|sin subida|faltan por entregar)\b/i;
const regexInstructor = /\b(instructor|cedula|cédula|documento|buscar instructor)\b/i;
const regexNumero = /\b\d{5,12}\b/;

let intencion = 'llm';
let tipoConsulta = 'resumen';
let busquedaParam = '';

if (regexCargaron.test(texto)) {
  intencion = 'consulta_db';
  tipoConsulta = 'cargaron';
} else if (regexPendientes.test(texto)) {
  intencion = 'consulta_db';
  tipoConsulta = 'pendientes';
} else if (regexInstructor.test(texto) || regexNumero.test(texto)) {
  intencion = 'consulta_db';
  tipoConsulta = 'instructor';
  const matchNum = texto.match(/\b\d{5,12}\b/);
  if (matchNum) {
    busquedaParam = matchNum[0];
  } else {
    busquedaParam = textoRaw.replace(/instructor|cédula|cedula|buscar|de|del|por/gi, '').trim();
  }
} else if (regexResumen.test(texto)) {
  intencion = 'consulta_db';
  tipoConsulta = 'resumen';
}

return [{
  json: {
    ...item,
    intencion,
    tipoConsulta,
    busquedaParam,
    textoOriginal: textoRaw
  }
}];

const items = $input.all();
const ctx = $('Detectar Intención Coordinador').first().json;
const tipo = ctx.tipoConsulta;

let msgText = '';

if (tipo === 'cargaron') {
  if (!items || items.length === 0 || !items[0].json.nombre_completo) {
    msgText = '📋 *Instructores con informes cargados:*\n\nAún no hay instructores con informes radicados en el sistema.';
  } else {
    const lineas = items.map((it, idx) => {
      const r = it.json;
      return `${idx + 1}. *${r.nombre_completo}* (CC ${r.numero_documento}): ${r.informes} informe(s)`;
    }).join('\n');
    msgText = `📋 *Instructores con informes radicados:*\n\n${lineas}\n\nTotal instructores con entregas: ${items.length}`;
  }
} else if (tipo === 'pendientes') {
  if (!items || items.length === 0 || !items[0].json.nombre_completo) {
    msgText = '✅ *Estado de entregas:*\n\n¡Excelente! Todos los instructores activos han cargado al menos un informe.';
  } else {
    const lineas = items.map((it, idx) => {
      const r = it.json;
      return `${idx + 1}. *${r.nombre_completo}* (CC ${r.numero_documento})`;
    }).join('\n');
    msgText = `⚠️ *Instructores sin informes cargados registrados:*\n\n${lineas}`;
  }
} else if (tipo === 'instructor') {
  if (!items || items.length === 0 || !items[0].json.nombre_completo) {
    msgText = `🔍 No se encontró ningún instructor con la búsqueda "${ctx.busquedaParam}". Verifica el nombre o la cédula.`;
  } else {
    const r = items[0].json;
    msgText = `👤 *Estado del Instructor ${r.nombre_completo}* (CC ${r.numero_documento}):\n\n• *Pendientes:* ${r.pendientes || 0}\n• *Validados:* ${r.validados || 0}\n• *Devueltos:* ${r.devueltos || 0}\n• *Total de informes:* ${r.total || 0}`;
  }
} else {
  const r = items[0]?.json || {};
  const pendientes = r.pendientes || 0;
  const validados = r.validados || 0;
  const devueltos = r.devueltos || 0;
  const total = r.total || 0;
  const tasa = r.tasa_cumplimiento != null ? r.tasa_cumplimiento : 0;

  msgText = `📊 *Resumen General de Informes STIMI:*\n\n• *Pendientes:* ${pendientes}\n• *Validados:* ${validados}\n• *Devueltos:* ${devueltos}\n• *Total cargados:* ${total}\n• *Tasa de cumplimiento:* ${tasa}%\n\n🦅 Puedes preguntarme por instructores específicos o por quienes faltan entregar.`;
}

return [{
  json: {
    telefono: ctx.telefono || '0000000000',
    mensaje: msgText,
    respuesta: msgText,
    output: msgText,
    text: msgText,
    ok: true,
    pregunta_log: ctx.textoOriginal || 'Consulta DB',
    origen: ctx.origen || 'pagina_web_coordinador'
  }
}];
